import {
  isRecord,
  parseQuickJsPresentation,
  parseQuickJsRequest,
  type QuickJsPresentation,
  type QuickJsRequest,
} from "./contract";

export interface QuickJsOptions {
  /** Override for bundlers with a different worker entry convention. */
  createWorker?: () => Worker;
  signal?: AbortSignal;
  /** Includes worker startup and WASM loading; must be 1–10000 ms. */
  timeoutMs?: number;
}

/** One disposable worker per evaluation. Pass only a complete script, never a streaming fragment. */
export function evaluateQuickJsInWorker(
  request: QuickJsRequest,
  options: QuickJsOptions = {}
): Promise<QuickJsPresentation> {
  return new Promise((resolve, reject) => {
    const snapshot = parseQuickJsRequest(request);
    const timeout = options.timeoutMs ?? 5000;
    if (!Number.isFinite(timeout) || timeout < 1 || timeout > 10_000) {
      throw new Error("Invalid worker timeout");
    }
    if (options.signal?.aborted) {
      throw new Error("QuickJS evaluation cancelled");
    }
    const worker = options.createWorker?.() ?? new Worker(new URL("./worker.ts", import.meta.url), { type: "module" });
    let settled = false;
    const finish = (error?: Error, result?: QuickJsPresentation) => {
      if (settled) {
        return;
      }
      settled = true;
      clearTimeout(timer);
      options.signal?.removeEventListener("abort", abort);
      worker.onmessage = null;
      worker.onerror = null;
      worker.onmessageerror = null;
      worker.terminate();
      if (error) {
        reject(error);
      } else {
        resolve(result ?? {});
      }
    };
    const abort = () => finish(new Error("QuickJS evaluation cancelled"));
    const timer = setTimeout(() => finish(new Error("QuickJS worker timed out")), timeout);
    options.signal?.addEventListener("abort", abort, { once: true });
    if (options.signal?.aborted) {
      abort();
      return;
    }
    worker.onerror = () => finish(new Error("QuickJS worker failed to load or execute"));
    worker.onmessageerror = () => finish(new Error("Invalid QuickJS worker message"));
    worker.onmessage = (event: MessageEvent<unknown>) => {
      try {
        const response = event.data;
        if (!isRecord(response) || response["ok"] !== true) {
          throw new Error("QuickJS rule failed or returned invalid output");
        }
        finish(undefined, parseQuickJsPresentation(response["presentation"], snapshot.fields));
      } catch (error) {
        finish(error instanceof Error ? error : new Error("Invalid QuickJS output"));
      }
    };
    try {
      worker.postMessage(snapshot);
    } catch (error) {
      finish(error instanceof Error ? error : new Error("Could not send QuickJS input"));
    }
  });
}

/** Flat, JSON-safe snapshots only. No protobuf messages, credentials, or host objects. */
export interface QuickJsRequest {
  fields: string[];
  source: string;
  values: Record<string, string | number | boolean | null>;
}
export type QuickJsPresentation = Record<string, { visible?: boolean; disabled?: boolean }>;
export const QUICKJS_TEXT_LIMIT = 16_384;
const reservedNames = new Set(["__proto__", "constructor", "prototype"]);
const fieldName = /^[A-Za-z_][A-Za-z0-9_]{0,127}$/u;

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function parseQuickJsRequest(value: unknown): QuickJsRequest {
  if (
    !isRecord(value) ||
    typeof value["source"] !== "string" ||
    !isRecord(value["values"]) ||
    !Array.isArray(value["fields"])
  ) {
    throw new Error("Expected source, scalar values, and explicit field names");
  }
  if (value["fields"].length > 200) {
    throw new Error("Too many fields");
  }
  const fields: string[] = [];
  const allowedFields = new Set<string>();
  for (const field of value["fields"]) {
    if (typeof field !== "string" || !fieldName.test(field) || reservedNames.has(field) || allowedFields.has(field)) {
      throw new Error("Invalid or duplicate field name");
    }
    fields.push(field);
    allowedFields.add(field);
  }
  if (value["source"].length > QUICKJS_TEXT_LIMIT) {
    throw new Error("Request limit exceeded");
  }
  const values: QuickJsRequest["values"] = {};
  for (const [key, item] of Object.entries(value["values"])) {
    if (
      !(
        allowedFields.has(key) &&
        (item === null ||
          typeof item === "string" ||
          typeof item === "boolean" ||
          (typeof item === "number" && Number.isFinite(item)))
      )
    ) {
      throw new Error("Expected known fields with finite scalar values");
    }
    values[key] = item;
  }
  if (JSON.stringify(values).length > QUICKJS_TEXT_LIMIT) {
    throw new Error("Input too large");
  }
  return { fields, source: value["source"], values };
}

export function parseQuickJsPresentation(value: unknown, fields: string[]): QuickJsPresentation {
  if (!isRecord(value)) {
    throw new Error("Expected presentation object");
  }
  const result: QuickJsPresentation = {};
  const allowedFields = new Set(fields);
  for (const [field, config] of Object.entries(value)) {
    if (!(allowedFields.has(field) && isRecord(config))) {
      throw new Error("Unknown field or invalid presentation");
    }
    const policy: { visible?: boolean; disabled?: boolean } = {};
    for (const [key, setting] of Object.entries(config)) {
      if ((key !== "visible" && key !== "disabled") || typeof setting !== "boolean") {
        throw new Error("Only boolean visible/disabled properties are allowed");
      }
      policy[key] = setting;
    }
    result[field] = policy;
  }
  return result;
}

import { getQuickJS } from "quickjs-emscripten";

import {
  isRecord,
  parseQuickJsPresentation,
  parseQuickJsRequest,
  QUICKJS_TEXT_LIMIT,
  type QuickJsPresentation,
} from "./contract";

/** Worker implementation. Use the worker client from a browser UI, not this function. */
export async function evaluateQuickJs(request: unknown): Promise<QuickJsPresentation> {
  const { source, values, fields } = parseQuickJsRequest(request);
  const input = JSON.stringify(values);
  if (source.length > QUICKJS_TEXT_LIMIT || input.length > QUICKJS_TEXT_LIMIT) {
    throw new Error("Input too large");
  }
  const QuickJS = await getQuickJS();
  const runtime = QuickJS.newRuntime();
  runtime.setMemoryLimit(8 * 1024 * 1024);
  runtime.setMaxStackSize(256 * 1024);
  const deadline = performance.now() + 50;
  runtime.setInterruptHandler(() => performance.now() >= deadline);
  const context = runtime.newContext();
  try {
    // No host functions or module loader. Capture serialization before running untrusted code.
    const result = context.evalCode(
      `"use strict"; (() => {
      const stringify = JSON.stringify.bind(JSON);
      const form = Object.freeze(JSON.parse(${JSON.stringify(input)}));
      const evaluate = (${source}\n);
      return stringify(evaluate(form));
    })()`,
      "form-rule.js"
    );
    if (result.error) {
      result.error.dispose();
      throw new Error("Script failed, exceeded resources, or is incomplete");
    }
    let text: string;
    try {
      if (context.typeof(result.value) !== "string") {
        throw new Error("Expected JSON output");
      }
      text = context.getString(result.value);
    } finally {
      result.value.dispose();
    }
    if (text.length > QUICKJS_TEXT_LIMIT) {
      throw new Error("Output too large");
    }
    const output: unknown = JSON.parse(text);
    if (!isRecord(output) || Object.keys(output).length !== 1 || !isRecord(output["fields"])) {
      throw new Error("Expected only a fields object");
    }
    return parseQuickJsPresentation(output["fields"], fields);
  } finally {
    context.dispose();
    runtime.dispose();
  }
}

import { evaluateQuickJs } from "./evaluator";

// This module is a worker entrypoint, never imported by the application directly.
globalThis.onmessage = async (event: MessageEvent<unknown>) => {
  try {
    const presentation = await evaluateQuickJs(event.data);
    globalThis.postMessage({ ok: true, presentation });
  } catch {
    // Do not send guest exceptions, stack traces, or input data back to the host.
    globalThis.postMessage({ ok: false });
  }
};

import type { FieldConfig } from "../core/field-model";
import type { QuickJsPresentation } from "./contract";

/** Always compose against the original base config, not the previous dynamic result. */
export function quickJsFieldConfig<FieldTypes = never>(
  presentation: QuickJsPresentation,
  base: Record<string, FieldConfig<FieldTypes, Record<string, unknown>>> = {}
): Record<string, FieldConfig<FieldTypes, Record<string, unknown>>> {
  const result: Record<string, FieldConfig<FieldTypes, Record<string, unknown>>> = { ...base };
  for (const [field, policy] of Object.entries(presentation)) {
    const original = base[field];
    result[field] = {
      ...original,
      ...(policy.visible === false ? { customData: { ...original?.customData, hidden: true } } : {}),
      ...(policy.disabled === true ? { inputProps: { ...original?.inputProps, disabled: true } } : {}),
    };
  }
  return result;
}

import { evaluateQuickJsInWorker, type QuickJsOptions } from "./client";
import {
  parseQuickJsPresentation,
  parseQuickJsRequest,
  type QuickJsPresentation,
  type QuickJsRequest,
} from "./contract";

/** Select from a host-owned reviewed catalog. Metadata is not a security approval mechanism. */
export interface ReviewedQuickJsRequest {
  fields: string[];
  rule: { id: string; version: string; source: string };
  values: QuickJsRequest["values"];
}

export interface QuickJsControllerState {
  error: string | null;
  presentation: QuickJsPresentation;
  status: "idle" | "pending" | "ready" | "error" | "disposed";
  submitting: boolean;
}

interface ControllerOptions extends Omit<QuickJsOptions, "signal"> {
  /** Trusted evaluator override for tests or alternative worker transports. */
  evaluate?: typeof evaluateQuickJsInWorker;
}

function prepare(request: ReviewedQuickJsRequest) {
  const { id, version } = request.rule;
  if (!(id.trim() && version.trim()) || id.length > 128 || version.length > 128) {
    throw new Error("Expected a reviewed rule ID and version");
  }
  const snapshot = parseQuickJsRequest({ ...request, source: request.rule.source });
  snapshot.fields.sort((a, b) => a.localeCompare(b));
  const identity = JSON.stringify([id, version, snapshot.source, snapshot.fields]);
  const key = JSON.stringify([identity, Object.entries(snapshot.values).sort(([a], [b]) => a.localeCompare(b))]);
  return { identity, key, snapshot };
}

/** Framework-independent store; update synchronously from every input/rule/schema change. */
export function createQuickJsController(options: ControllerOptions = {}) {
  const { evaluate = evaluateQuickJsInWorker, ...workerOptions } = options;
  const listeners = new Set<() => void>();
  let state: QuickJsControllerState = Object.freeze({
    error: null,
    presentation: Object.freeze({}),
    status: "idle",
    submitting: false,
  });
  let revision = 0;
  let active: AbortController | undefined;
  let accepted: ReturnType<typeof prepare> | undefined;
  let identity: string | undefined;
  let submitting = false;

  function stateIsLive() {
    return state.status !== "disposed";
  }

  function publish(next: QuickJsControllerState) {
    state = Object.freeze(next);
    for (const listener of listeners) {
      listener();
    }
  }

  function invalidate() {
    if (state.status === "disposed") {
      return;
    }
    revision += 1;
    active?.abort();
    active = undefined;
    accepted = undefined;
    publish({ ...state, error: null, status: "idle" });
  }

  function resetPresentation(prepared: ReturnType<typeof prepare>) {
    if (prepared.identity !== identity) {
      ({ identity } = prepared);
      publish({ ...state, presentation: Object.freeze({}) });
    }
  }

  async function update(request: ReviewedQuickJsRequest): Promise<void> {
    if (state.status === "disposed") {
      throw new Error("QuickJS controller disposed");
    }
    revision += 1;
    const current = revision;
    active?.abort();
    accepted = undefined;
    const abort = new AbortController();
    active = abort;
    // Invalidate readiness before parsing or calling any asynchronous code.
    publish({ ...state, error: null, status: "pending" });
    if (current !== revision) {
      return;
    }
    let prepared: ReturnType<typeof prepare>;
    let presentation: QuickJsPresentation;
    try {
      prepared = prepare(request);
      resetPresentation(prepared);
      if (current !== revision) {
        return;
      }
      presentation = parseQuickJsPresentation(
        await evaluate(prepared.snapshot, {
          signal: abort.signal,
          ...workerOptions,
        }),
        prepared.snapshot.fields
      );
    } catch {
      if (current === revision) {
        active = undefined;
        publish({ ...state, error: "Could not evaluate form rules. Retry before submitting.", status: "error" });
      }
      return;
    }
    if (current !== revision) {
      return;
    }
    for (const policy of Object.values(presentation)) {
      Object.freeze(policy);
    }
    accepted = prepared;
    active = undefined;
    publish({ ...state, error: null, presentation: Object.freeze(presentation), status: "ready" });
  }

  /** Call after schema validation, passing the exact current snapshot. Never pass unprojected secrets. */
  async function submit<T>(
    request: ReviewedQuickJsRequest,
    action: (values: QuickJsRequest["values"]) => T | Promise<T>
  ): Promise<T> {
    if (state.status !== "ready" || !accepted || submitting) {
      throw new Error("Form rules are not ready for submission");
    }
    if (prepare(request).key !== accepted.key) {
      throw new Error("Form inputs or rules changed before submission");
    }
    const values = { ...accepted.snapshot.values };
    const current = revision;
    submitting = true;
    try {
      publish({ ...state, submitting: true });
      if (current !== revision) {
        throw new Error("Form inputs or rules changed before submission");
      }
      return await action(values);
    } finally {
      submitting = false;
      if (stateIsLive()) {
        publish({ ...state, submitting: false });
      }
    }
  }

  function dispose() {
    if (state.status === "disposed") {
      return;
    }
    revision += 1;
    active?.abort();
    active = undefined;
    accepted = undefined;
    publish({ ...state, error: null, status: "disposed", submitting: false });
    listeners.clear();
  }

  return {
    dispose,
    getSnapshot: () => state,
    invalidate,
    submit,
    subscribe(listener: () => void) {
      if (state.status === "disposed") {
        return () => undefined;
      }
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    update,
  };
}
